adcs_vec3_t unit_axis = {0};
adcs_vec3_t command_dipole = {0};
adcs_vec3_t expected_torque = {0};
double expected_norm_sq = 0.0;
double measured_norm = 0.0;
double projection = 0.0;
double alignment_cosine = 0.0;
int is_projection_adequate = 0;

// 1. Check for NULL pointers
if (pt_input.field_body_t == NULL || pt_input.measured_torque_nm == NULL) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 2. Check finite inputs
if (!adcs_is_finite_vec3(pt_input.field_body_t) || 
    !adcs_is_finite_vec3(pt_input.measured_torque_nm) ||
    !isfinite(pt_config.test_dipole_a_m2) ||
    !isfinite(pt_config.min_fraction) ||
    !isfinite(pt_config.confirm_samples) ||
    !isfinite(pt_config.max_samples_per_phase)) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 3. Check enable is binary (0 or 1)
if (pt_input.enable != 0 && pt_input.enable != 1) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 4. Check configuration ranges
if (pt_config.test_dipole_a_m2 <= 0.0) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}
if (pt_config.min_fraction <= 0.0 || pt_config.min_fraction > 1.0) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}
if (pt_config.confirm_samples < 1 || pt_config.confirm_samples > 20) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}
if (pt_config.max_samples_per_phase < 1 || pt_config.max_samples_per_phase > 200) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 5. Normalize test axis
if (adcs_vec3_normalize(&pt_config.test_axis_body, ADCS_EPS_NORM, &unit_axis) != ADCS_OK) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 6. Check vector norms are valid geometry
double field_norm = adcs_vec3_norm(pt_input.field_body_t);
double torque_norm = adcs_vec3_norm(*pt_input.measured_torque_nm);

if (field_norm <= ADCS_EPS_NORM || torque_norm <= ADCS_EPS_NORM) {
    pt_state.mode = PT_FAULT;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 7. Handle Disable
if (pt_input.enable == 0) {
    pt_state.mode = PT_IDLE;
    pt_state.confirm_count = 0;
    pt_state.sample_count = 0;
    pt_output.mode = PT_IDLE;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 8. If already in PASS or FAULT, remain latched
if (pt_state.mode == PT_PASS || pt_state.mode == PT_FAULT) {
    pt_output.mode = pt_state.mode;
    pt_output.command_a_m2 = (adcs_vec3_t){0};
    pt_output.expected_torque_nm = (adcs_vec3_t){0};
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 9. Determine current phase command and expected torque
double dipole_sign = 1.0;
if (pt_state.mode == PT_NEGATIVE) {
    dipole_sign = -1.0;
}

command_dipole = adcs_vec3_scale(&unit_axis, dipole_sign * pt_config.test_dipole_a_m2);
expected_torque = adcs_vec3_cross(&command_dipole, pt_input.field_body_t);
expected_norm_sq = adcs_vec3_dot(&expected_torque, &expected_torque);

// Calculate projection
projection = adcs_vec3_dot(pt_input.measured_torque_nm, &expected_torque);

// Calculate alignment cosine
double expected_norm = sqrt(expected_norm_sq);
if (expected_norm <= ADCS_EPS_NORM) {
     pt_state.mode = PT_FAULT;
     pt_output.mode = PT_FAULT;
     pt_output.command_a_m2 = (adcs_vec3_t){0};
     pt_output.expected_torque_nm = (adcs_vec3_t){0};
     pt_output.projection_nm2 = 0.0;
     pt_output.alignment_cosine = 0.0;
     return;
}

alignment_cosine = projection / (torque_norm * expected_norm);

// 10. Check projection adequacy
if (projection >= pt_config.min_fraction * expected_norm_sq) {
    is_projection_adequate = 1;
} else {
    is_projection_adequate = 0;
}

// 11. Update counters and state
if (is_projection_adequate) {
    pt_state.confirm_count++;
    pt_state.sample_count = 0; 

    if (pt_state.confirm_count >= pt_config.confirm_samples) {
        if (pt_state.mode == PT_IDLE) {
            pt_state.mode = PT_NEGATIVE;
        } else if (pt_state.mode == PT_NEGATIVE) {
            pt_state.mode = PT_PASS;
        }
        pt_state.confirm_count = 0;
        pt_state.sample_count = 0;
    }
} else {
    pt_state.confirm_count = 0; 
    pt_state.sample_count++;

    if (pt_state.sample_count >= pt_config.max_samples_per_phase) {
        pt_state.mode = PT_FAULT;
        pt_state.confirm_count = 0;
        pt_state.sample_count = 0;
    }
}

// 12. Set output command
if (pt_state.mode == PT_PASS || pt_state.mode == PT_FAULT) {
    pt_output.command_a_m2 = (adcs_vec3_t){0};
} else {
    pt_output.command_a_m2 = command_dipole;
}

// 13. Assign outputs
pt_output.mode = pt_state.mode;
pt_output.expected_torque_nm = expected_torque;
pt_output.projection_nm2 = projection;
pt_output.alignment_cosine = alignment_cosine;

